def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    if n >= 10:
        recent_op = op[-10:]
        if recent_op.count('D') >= 8:
            return 'D'
    if n >= 2 and my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
        return 'C'
    if op[-1] == 'D':
        if n >= 2 and op[-2] == 'C':
            if my[-1] == 'D' or my[-2] == 'D':
                return 'C'
        return 'D'
    return 'C'
